function registerDatumShift(rule) { const k = DATUM_SHIFTS.findIndex((r) => r.id === rule.id); if (k >= 0) DATUM_SHIFTS[k] = rule; else DATUM_SHIFTS.push(rule); }

const _grids = new Set();
