    if (wkt) nd = def.replace(/,\s*TOWGS84\s*\[[^\]]*\]/ig, '').replace(/(DATUM\s*\[\s*"[^"]*"\s*,\s*SPHEROID\s*\[[^\]]*\])/i, `$1,TOWGS84[${p.join(',')}]`);
