    parts.push(`${nm} ${dir === 'from' ? '→' : '←'} WGS 84 by ${what}${s.params ? ` (${fmtP(s.params.slice(0, 3))} m${s.kind === 'helmert7' ? ' + rotations, scale' : ''})` : ''}`);
